{"implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        normalized = gain / call['prediction_tokens']
        is_accepted = call['parseable'] and normalized >= threshold
        if is_accepted:
            accepted.append(call_id)
        diagnostics.append({
            'accepted': is_accepted,
            'call_id': call_id,
            'normalized_gain': round(normalized, 8)
        })
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }"}
